package android.graphics; import android.content.res.Resources; import java.io.InputStream; public class BitmapFactory { public static class Options { public int outWidth,outHeight,inSampleSize; public boolean inJustDecodeBounds; } public static Bitmap decodeResource(Resources r,int id){return new Bitmap(1,1,id);} public static Bitmap decodeResource(Resources r,int id,Options o){return decodeResource(r,id);} public static Bitmap decodeByteArray(byte[] a,int off,int len){return new Bitmap(1,1,0);} public static Bitmap decodeByteArray(byte[] a,int off,int len,Options o){return decodeByteArray(a,off,len);} public static Bitmap decodeStream(InputStream s){return new Bitmap(1,1,0);} public static Bitmap decodeStream(InputStream s,Rect r,Options o){return decodeStream(s);} }